// The credit agent, drawn as palette-indexed layers. Original character: a friendly businessman.
// Short tufty hair with highlights, navy suit with a light and a dark side, white shirt with collar
// points, red tie with a knot and stripes, pocket square, name badge. Calm open eyes, soft brows, a
// warm smile, a light blush. Facial hair is its own layer (none, moustache, moustache with stubble).
// Since 111 the head is longer (style-ref-1 proportions): the face is taller than wide, eyes near the middle.
// The pixels live in art.ts (generated by the design script, editable by hand); this file places them.
// Coordinates are local to the 49x60 character box (see ART-GUIDE.md); the head rises 5 rows above it.
import { flipX, sprite, transpose, type Sprite } from '../raster'
import {
  BROWS_ART, BUBBLE_ART, EYES_ART, GLASSES_ART, HANDS_ART, HEAD_ART, ITEMS_ART, MOUSTACHE_ART, MOUTHS_ART, STUBBLE_ART,
  TORSO_ART,
} from './art'

function sprites<K extends string>(art: Record<K, readonly string[]>): Record<K, Sprite> {
  const out = {} as Record<K, Sprite>
  for (const k of Object.keys(art) as K[]) out[k] = sprite(art[k])
  return out
}

// ---------- head (25x31) at local (12, -5); centre column 12 ----------
// Tufts rows 0-1, hair to row 8 (fringe and sideburns lower), face skin rows 9-29 (17 wide, about 4:5),
// brows row 15, eyes 17-19, ears 17-22, nose 21-22, moustache 23-24, mouth line 25, chin 29.
// The chin outline sits on torso row 1, so two rows of neck show above the collar.
export const HEAD_POS = { x: 12, y: -5 }
export const HEAD = sprite(HEAD_ART)

/**
 * Eyes 13x4 at head (6, 16); the eyes themselves are rows 1-3 (row 0 is empty headroom in every frame). Each eye is
 * 4x3: a 2x3 iris with a white highlight at its top-left and white sclera on both sides, no lid line on top.
 */
export const EYES_POS = { x: 6, y: 16 }
export const EYES = sprites(EYES_ART)
export type EyeKey = keyof typeof EYES

/** Eyebrows 13x3 at head (6, 14). 1 px soft brows, 4 wide, neutral on row 1 (one free row above the eyes). */
export const BROWS_POS = { x: 6, y: 14 }
export const BROWS = sprites(BROWS_ART)
export type BrowKey = keyof typeof BROWS

/** Mouth 9x4 at head (8, 23), main line on row 2. Rest mouths per emote plus the talking frames small, open, wide. */
export const MOUTH_POS = { x: 8, y: 23 }
export const MOUTHS = sprites(MOUTHS_ART)
export type MouthKey = keyof typeof MOUTHS

/** Coach glasses 21x5 at head (2, 16): thin dark frames around each eye, temples to the ears. */
export const GLASSES_POS = { x: 2, y: 16 }
export const GLASSES = sprite(GLASSES_ART)

// ---------- facial hair: its own layer, drawn with the head group ----------
export const FACIAL_HAIR = ['none', 'moustache', 'moustache-stubble'] as const
/** none: clean-shaven; moustache: a neat moustache; moustache-stubble (default since 111): the moustache with light stubble. */
export type FacialHair = (typeof FACIAL_HAIR)[number]
/** The facial hair the agent starts with (option C, picked by the user in 111). */
export const DEFAULT_FACIAL_HAIR: FacialHair = 'moustache-stubble'
/** 110 called moustache-stubble 'stubble'; that name is still accepted. */
export function normalizeFacialHair(f: FacialHair | 'stubble'): FacialHair {
  return f === 'stubble' ? 'moustache-stubble' : f
}
/** Stubble covers the head sprite: a flat darker skin tone along the jaw, the chin and around the mouth. */
export const STUBBLE = sprite(STUBBLE_ART)
/** Moustache 9x2 at head (8, 23), drawn over the mouth so the upper lip hides under it. */
export const MOUSTACHE_POS = { x: 8, y: 23 }
export const MOUSTACHE = sprite(MOUSTACHE_ART)

// ---------- torso (41x36) at local (4, 24); the desk hides it from torso y 31 ----------
export const TORSO_POS = { x: 4, y: 24 }
export const TORSO = sprite(TORSO_ART)

/** Shoulder joints (local coords); arms hang from here. */
export const SHOULDER_L = { x: 9, y: 33 }
export const SHOULDER_R = { x: 39, y: 33 }

// ---------- hands (anchored at their centre) ----------
const H = sprites(HANDS_ART)
export const HANDS = {
  rest: H.rest,
  grip: H.grip,
  open: H.open,
  openL: flipX(H.open),
  pointDown: H.pointDown,
  pointRight: transpose(H.pointDown),
  flat: H.flat,
} satisfies Record<string, Sprite>
export type HandKey = keyof typeof HANDS

// ---------- held items (anchored at their top-left, local coords given by the pose) ----------
export const ITEMS = sprites(ITEMS_ART)
export type ItemKey = keyof typeof ITEMS

/** Thinking bubble (drawn in scene coords next to the head). */
export const BUBBLE = sprite(BUBBLE_ART)
